353	// An action node either keeps the legacy `message` behavior, names a business
354	// operation the caller supplies at run time, and/or declares a compensation
355	// operation that undoes its business effect. Both retry blocks are optional
356	// and, absent, mean exactly one attempt with no waiting.
357	function compileAction(node) {
358	  let name = null;
359	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
360	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
361	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
362	    }
363	    name = node.operation;
364	  }
365	
366	  let retry = { ...DEFAULT_RETRY };
367	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
368	    if (!name) {
369	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
370	    }
371	    retry = compileRetry(node.retry, `action node ${node.id}`);
372	  }
373	
374	  let compensation = null;
375	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
376	    if (!isUsableObject(node.compensation)) {
377	      throw new Error(`action node ${node.id}: compensation must be an object`);
378	    }
379	    if (!name) {
380	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
381	    }
382	    const config = node.compensation;
383	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
384	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
385	    }
386	    let compRetry = { ...DEFAULT_RETRY };
387	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
388	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
389	    }
390	    compensation = { name: config.operation, retry: compRetry };
391	  }
392	
393	  // A legacy message action (no operation) may carry a structured object or
394	  // array as its message, and the output it saves is snapshotted per run. A
395	  // value the structured clone algorithm cannot deliver — a bare function or
396	  // a function nested inside an object/array — is a definition error naming
397	  // the action and the reason, for every message action including actions on
398	  // untaken branches and entry-unreachable ones. An action that names an
399	  // operation ignores its message entirely, so an unused uncloneable message
400	  // is never rejected for it.
401	  //
402	  // A value that clones but whose clone retains shared memory is rejected for
403	  // the same reason the run input and operation return values are: cloning a
404	  // SharedArrayBuffer (or a typed array / DataView backed by one) "succeeds"
405	  // while the clone keeps sharing the underlying bytes, so the independent
406	  // output copy the action promises — including against the definition's own
407	  // message, which the engine clones again at execution time — could not be
408	  // guaranteed. The check therefore runs on the cloned value with the same
409	  // clone-shaped traversal (containsSharedMemory): shared memory placed only
410	  // where cloning drops it (an attached property of a Date/RegExp, a
411	  // non-enumerable property, an Error own property other than cause) is
412	  // discarded with that property and never condemns the message.
413	  if (name === null && Object.hasOwn(node, 'message') && node.message !== undefined) {
414	    let cloned;
415	    try {
416	      cloned = structuredClone(node.message);
417	    } catch {
418	      throw new Error(`action node ${node.id}: message must be a structured-cloneable value (objects and arrays must not contain functions)`);
419	    }
420	    if (containsSharedMemory(cloned)) {
421	      throw new Error(`action node ${node.id}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`);
422	    }
423	  }
424	
425	  return { name, retry, compensation };
426	}
427	
428	// An end node's result is delivered to the caller verbatim for primitives
429	// (null, undefined, strings, numbers, booleans), but an object or array result
430	// must be structured-clonable. The independent-copy promise is enforced at
431	// BOTH moments it can be observed:
432	//
433	//  1. At validation time (compileEndResult below), for every end node in the
434	//     definition — including nodes on untaken branches and nodes the entry
435	//     cannot reach — so a statically invalid result is rejected before any
436	//     node can run.
437	//  2. At the end node's own execution moment (captureEndResult), against the
438	//     value actually about to be recorded: validation cannot see what an
439	//     enumerable getter returns on its later read, nor what a preceding
440	//     business operation or another activated branch does to the configured
441	//     result before this end runs. Only the content this run will save is
442	//     judged.
443	//
444	// The two failure kinds, in priority order: a value that cannot be
445	// structured-cloned (a bare function, a function nested in an object/array, a
446	// getter that throws, etc.), and a value that clones but whose clone retains
447	// shared memory — cloning a SharedArrayBuffer (or a typed array / DataView
448	// backed by one) "succeeds" while the clone keeps sharing the underlying
449	// bytes, so the caller could rewrite the returned bytes and silently change
450	// the definition and every later run. Uncloneability takes precedence when a
451	// result carries both. As with legacy messages, run inputs and operation
452	// returns, the clone is produced first and judged with containsSharedMemory:
453	// only shared memory the clone actually retains condemns the result (an
454	// attached property of a Date/RegExp, a non-enumerable or symbol-keyed
455	// property, an Error own property other than cause are discarded by the clone
456	// and never inspected).
457	const END_RESULT_UNCLONEABLE_MESSAGE = nodeId =>
458	  `end node ${nodeId}: result must be a structured-cloneable value (objects and arrays must not contain functions)`;
459	const END_RESULT_SHARED_MEMORY_MESSAGE = nodeId =>
460	  `end node ${nodeId}: result contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this end result is not supported`;
461	
462	function compileEndResult(node) {
463	  if (!Object.hasOwn(node, 'result') || node.result === undefined) return;
464	  let cloned;
465	  try {
466	    cloned = structuredClone(node.result);
467	  } catch {
468	    throw new Error(END_RESULT_UNCLONEABLE_MESSAGE(node.id));
469	  }
470	  if (containsSharedMemory(cloned)) {
471	    throw new Error(END_RESULT_SHARED_MEMORY_MESSAGE(node.id));
472	  }
473	}
474	
475	// Reads the end node's configured result at the node's own execution moment
476	// and produces the independent copy that will be recorded and returned. This
477	// re-enforces, for exactly the content this run is about to save, the promise
478	// validation already made for the value as it was then:
479	//
480	//   - the value is read exactly once here, via structuredClone's own read.
481	//     There is no separate inspection pass over the original, so an
482	//     enumerable getter's return order is never disturbed (the clone is the
483	//     only read), and a getter that returned ordinary data during validation
484	//     but returns shared memory — or a function — when this end executes is
485	//     caught on the value that would actually have been saved;
486	//   - shared memory the clone retains is rejected (containsSharedMemory runs
487	//     on the clone), while shared memory placed only where cloning drops it
488	//     is discarded with that property and never condemns an otherwise-legal
489	//     result.
490	//
491	// Uncloneability takes precedence over shared memory, matching validation:
492	// the clone is attempted first and its failure short-circuits before the
493	// shared-memory traversal. An unset, undefined or null result still becomes
494	// null (structuredClone(null) === null), while 0, false and "" pass through.
495	//
496	// Any failure is thrown here as an ordinary Error naming the end node rather
497	// than recorded as a run status: the synchronous entry propagates it and the
498	// asynchronous entry's rejected Promise carries it. It is never an
499	// action_failed — the end node has no retry budget — and it neither consumes
500	// business-action retries nor triggers compensation, and no "completed"
501	// result is produced.
502	function captureEndResult(node) {
503	  let cloned;
504	  try {
505	    // `node.result ?? null` is the root value's single read (an unset,
506	    // undefined or null result becomes null; 0, false and "" pass through);
507	    // every nested enumerable accessor is read only by structuredClone, so
508	    // this never adds a read that could change a getter's return order. A
509	    // root getter that throws, a nested/root getter that throws while the
510	    // clone reads it, and a value that cannot be cloned at all (a function)
511	    // all surface as the same end-node result error.
512	    cloned = structuredClone(node.result ?? null);
513	  } catch {
