import { executeWorkflow, executeWorkflowAsync, validateWorkflow } from './src/engine.js';
import assert from 'node:assert/strict';

const wf = message => ({
  id: 'w', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'note' },
    { id: 'note', type: 'action', message, next: 'done' },
    { id: 'done', type: 'end', result: 'ok' },
  ],
});

// 1. getter: ordinary at validation, SharedArrayBuffer at execution
{
  let reads = 0;
  const message = { get flip() { reads += 1; return reads === 1 ? 'ordinary' : new SharedArrayBuffer(4); } };
  const w = wf(message);
  assert.doesNotThrow(() => validateWorkflow(w));
  assert.equal(reads, 1);
  assert.throws(() => executeWorkflow(w, {}), e =>
    /action node note: message contains shared memory/.test(e.message)
    && /SharedArrayBuffer/.test(e.message)
    && /independent copies cannot be guaranteed/.test(e.message)
    && !(e instanceof TypeError));
  assert.equal(reads, 2, 'exactly one execution-time read');
  // async entry rejects, no action_failed
  let reads2 = 0;
  const message2 = { get flip() { reads2 += 1; return reads2 === 1 ? 'ordinary' : new SharedArrayBuffer(4); } };
  await assert.rejects(() => executeWorkflowAsync(wf(message2), {}), /action node note: message contains shared memory/);
  assert.equal(reads2, 2);
  console.log('1 ok: getter flips to SAB at execution');
}

// 2. business op swaps plain buffer for shared before the message action runs; no compensation, no retry consumed
{
  const w = {
    id: 'w2', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'early' },
      { id: 'early', type: 'action', operation: 'op', compensation: { operation: 'undo' }, next: 'note' },
      { id: 'note', type: 'action', message: { bytes: new Uint8Array([1,2]) }, next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  let compensated = 0;
  await assert.rejects(() => executeWorkflowAsync(w, {}, {
    op: () => { w.nodes[2].message.bytes = new Uint8Array(new SharedArrayBuffer(2)); return 'e'; },
    undo: () => { compensated += 1; },
  }), /action node note: message contains shared memory/);
  assert.equal(compensated, 0);
  assert.equal(Object.hasOwn(w.nodes[2], 'message'), true);
  console.log('2 ok: business-op swap rejected, no compensation');
}

// 3. message becomes uncloneable at execution (function swapped in / getter throws)
{
  const w = wf({ data: 'plain' });
  const w2 = {
    id: 'w3', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'early' },
      { id: 'early', type: 'action', operation: 'op', next: 'note' },
      { id: 'note', type: 'action', message: { data: 'plain' }, next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  await assert.rejects(() => executeWorkflowAsync(w2, {}, {
    op: () => { w2.nodes[2].message.data = () => 'fn'; return 'e'; },
  }), /action node note: message must be a structured-cloneable value/);

  const throwing = { get boom() { throw new Error('nope'); } };
  // validation: getter throws -> uncloneable at validation too, so use a getter that throws only on 2nd read
  let n = 0;
  const lateThrow = { get boom() { n += 1; if (n > 1) throw new Error('late'); return 'fine'; } };
  const w3 = wf(lateThrow);
  assert.doesNotThrow(() => validateWorkflow(w3));
  assert.throws(() => executeWorkflow(w3, {}), /action node note: message must be a structured-cloneable value/);
  console.log('3 ok: uncloneable at execution stops with node id');
}

// 4. legal new value at execution is what later nodes read
{
  let n = 0;
  const message = { get v() { n += 1; return n === 1 ? 'old' : 'fresh'; } };
  const w = {
    id: 'w4', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'note' },
      { id: 'note', type: 'action', message, next: 'check' },
      { id: 'check', type: 'condition', condition: { outputField: { nodeId: 'note', path: 'v' }, operator: 'eq', value: 'fresh' }, then: 'yes', else: 'no' },
      { id: 'yes', type: 'end', result: 'fresh-read' },
      { id: 'no', type: 'end', result: 'stale' },
    ],
  };
  const run = executeWorkflow(w, {});
  assert.equal(run.result, 'fresh-read');
  assert.equal(run.context.output.note.v, 'fresh');
  console.log('4 ok: execution-time value is saved and read downstream');
}

// 5. isolation both ways after success
{
  const message = { deep: { x: 1 }, buf: new Uint8Array([1,2,3]).buffer };
  const w = wf(message);
  const run = executeWorkflow(w, {});
  run.context.output.note.deep.x = 99;
  new Uint8Array(run.context.output.note.buf).fill(9);
  assert.equal(message.deep.x, 1);
  assert.deepEqual([...new Uint8Array(message.buf)], [1,2,3]);
  message.deep.x = 55;
  assert.equal(run.context.output.note.deep.x, 99);
  console.log('5 ok: output and definition message are mutually isolated');
}

// 6. no success output left, no later node runs, no completed/action_failed
{
  const w = {
    id: 'w6', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'note' },
      { id: 'note', type: 'action', message: 'ok', next: 'later' },
      { id: 'later', type: 'action', operation: 'op', next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  let laterRan = 0;
  w.nodes[1].message = { get s() { return new SharedArrayBuffer(2); } };
  // validation would reject this; confirm validation unchanged (still rejects)
  assert.throws(() => validateWorkflow(w), /message contains shared memory/);
  console.log('6 ok: validation-time behavior unchanged');
}

// 7. shared memory only in clone-dropped property at execution time is fine
{
  const message = { when: new Date(0) };
  const w = {
    id: 'w7', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'early' },
      { id: 'early', type: 'action', operation: 'op', next: 'note' },
      { id: 'note', type: 'action', message, next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  const run = await executeWorkflowAsync(w, {}, {
    op: () => { message.when.aux = new SharedArrayBuffer(4); return 'e'; },
  });
  assert.equal(run.status, 'completed');
  assert.ok(run.context.output.note.when instanceof Date);
  assert.equal(run.context.output.note.when.aux, undefined);
  console.log('7 ok: dropped-property shared memory does not condemn');
}

// 8. defaults and primitives unchanged
{
  for (const [m, expected] of [[undefined, 'action:note'], [null, 'action:note'], ['', ''], [0, 0], [false, false]]) {
    const w = wf(m);
    assert.equal(executeWorkflow(w, {}).context.output.note, expected);
  }
  console.log('8 ok: default/primitive rules unchanged');
}
console.log('all execution-time scenarios verified');
